mapper.select:
SELECT r.id, r.member_id, r.equipment_id, r.rent_time, r.return_time, r.rent_fee, r.deposit, r.status, r.operator_id, r.create_time, m.name AS member_name, m.card_no, e.code AS equipment_code, e.category FROM equipment_rental r LEFT JOIN member m ON m.id = r.member_id LEFT JOIN equipment e ON e.id = r.equipment_id
AND r.member_id = #{memberId} AND r.status = #{status}
ORDER BY r.create_time DESC
